                                  'def _club_copy_json(value, stack=None):\n'
                                  '    kind=type(value)\n'
                                  '    if kind in (str,int,float,bool,type(None)):return value\n'
                                  "    if kind not in (list,tuple,dict):raise TypeError('Pure calculation "
                                  "accepts exact JSON builtins only')\n"
                                  '    stack=set() if stack is None else stack\n'
                                  "    if id(value) in stack:raise ValueError('Circular JSON input')\n"
                                  '    stack.add(id(value))\n'
                                  '    try:\n'
                                  '        if kind is dict:\n'
                                  '            if any(type(key) not in (str,int,float,bool,type(None)) for '
                                  "key in value):raise TypeError('Non-JSON pure mapping key')\n"
                                  '            return {key:_club_copy_json(item,stack) for key,item in '
                                  'value.items()}\n'
                                  '        result=[_club_copy_json(item,stack) for item in value]\n'
                                  '        return tuple(result) if kind is tuple else result\n'
                                  '    finally:stack.remove(id(value))\n'
