  'def verify_fixture_published_history(root, selection, *, club_layer=False):\n'
  '    old = fixture_predecessor_selection(selection)\n'
  '    ensure_fixture_7bf_commit(root)\n'
  "    headers = checked(['git', 'cat-file', '-p', FIXTURE_BASE_COMMIT], root).split('\\n\\n', "
  '1)[0].splitlines()\n'
  "    require([r[5:] for r in headers if r.startswith('tree ')] == [FIXTURE_BASE_TREE]\n"
  "            and [r[7:] for r in headers if r.startswith('parent ')] == [MERCHANT_BASE_COMMIT],\n"
  "            'Real published3cbc must have exact tree and sole7bf parent')\n"
  "    changes = checked(['git', 'diff', '--name-status', '--no-renames', MERCHANT_BASE_COMMIT, "
  'FIXTURE_BASE_COMMIT], root).splitlines()\n'
  "    require(len(changes) == 7 and set(changes) == set(MERCHANT_LAYER['allowed_changes']),\n"
  "            'Published3cbc differs from exact seven-path merchant layer')\n"
  "    expected_before = {p: ['100644', 'blob', v['blob']] for p, v in MERCHANT_BEFORE.items()}\n"
  '    require(merchant_tree_entries(root, MERCHANT_BASE_COMMIT, MERCHANT_PATHS) == expected_before,\n'
  "            'Changed real7bf merchant predecessors')\n"
  '    incoming = merchant_current_inputs(old, root, fixture_layer=True, club_layer=club_layer)\n'
